\label{lem:fish} Let $S$ be an inverse semigroup, let $A$ be a non-empty subset and let $s \in S$.
\begin{enumerate}
\item If $\bigwedge A$ exists then $\bigwedge_{a \in A}sa$ exists and $s\left( \bigwedge A \right) = \bigwedge_{a \in A}sa$. 
\item If $\bigwedge A$ exists then $\bigwedge_{a \in A}as$ exists and $\left( \bigwedge A \right)s = \bigwedge_{a \in A}as$. 
\end{enumerate}

\label{lem:oj} Let $S$ be an inverse semigroup.
\begin{enumerate}
\item $a \perp b$ implies that $ca \perp cb$ for any $c \in S$.
\item $a \perp b$ implies that $ac \perp bc$ for any $c \in S$.
\end{enumerate}

\label{lem:orthogonal} Let $s = \bigvee_{i=1}^{m} s_{i}$ where the $s_{i}$ are distinct and non-zero.
Then there is an orthogonal set of elements $\{t_{1}, \ldots, t_{m}\}$ such that
\begin{enumerate}
\item $s = \bigvee_{i=1}^{m} t_{i}$.
\item For each $i$, we have that $t_{i} \leq s_{i}$.
\end{enumerate}

\label{prop:definition} The following are equivalent.
\begin{enumerate}
\item $S$ is a Boolean inverse semigroup.
\item $S$ has all binary orthogonal joins, multiplication distributes over binary orthogonal joins, 
and its semilattice of idempotents forms a Boolean algebra with respect to the natural partial order.
\end{enumerate}

\label{prop:boolean-congruence-free} 
A Boolean inverse semigroup is simple if and only if
it is $0$-simplifying and fundamental.

\label{ex:solomon}
{\em Let $\mathbf{2} = \{0,1\}$, the two-element unital Boolean algebra.
Then $M_{n}(\mathbf{2})$ is the Boolean inverse monoid of $n \times n$ rook matrices in the sense of Solomon \cite{Solomon}, 
and so is isomorphic to the finite symmetric inverse monoid on $n$ letters $\mathscr{I}_{n}$.}

\label{lem:two} 
Let $S$ be a Boolean inverse semigroup.
For each $a \in S$, the set $\theta (a)$ is a local bisection of the groupoid $\mathsf{A}(S)$.

\label{lem:bordeaux1} \mbox{}
\begin{enumerate}

\item A finite Boolean inverse monoid is fundamental if and only its groupoid of atoms is principal.

\item A finite Boolean inverse monoid is $0$-simplifying if and only if its groupoid of atoms is connected.

\end{enumerate}

\label{cor:finite-stuff}\mbox{}
\begin{enumerate}

\item The finite $0$-simplifying Boolean inverse monoids are isomorphic to $M_{n}(G^{0})$ where $G$ is a finite group.

\item The finite fundamental Boolean inverse monoids are isomorphic to the finite direct products $\mathscr{I}_{n_{1}} \times \ldots \times \mathscr{I}_{n_{r}}$.

\item The finite simple Boolean inverse monoids are isomorphic to $\mathscr{I}_{n}$.

\end{enumerate}

\label{lem:when-semisimple} 
An inverse semigroup $S$ is semisimple if and only if the sets $e^{\downarrow}$ are finite for
all idempotents $e$ of $S$.

\label{prop:atoms-semisimple} In a Boolean inverse semigroup $S$, the following assertions are equivalent:
\begin{enumerate}
\item $S$ is semisimple.
\item Each non-zero element is above an atom and every element is a finite join of atoms.
\end{enumerate}

\label{them:discrete-topology}
Let $S$ be a Boolean inverse semigroup.
\begin{enumerate}
\item When $S$ is a semisimple,
the groupoid $\mathsf{G}(S)$ is isomorphic with the groupoid of atoms of $S$
under the restricted product.
\item $S$ is semisimple if and only if the topology on $\mathsf{G}(S)$ is discrete.
\end{enumerate}

\label{lem:semisimple-bordeaux} \mbox{}
\begin{enumerate} 
\item A semisimple inverse semigroup is fundamental if and only if its groupoid of atoms is principal.
\item A semisimple Boolean inverse semigroup is $0$-simplifying if and only if its groupoid of atoms is connected.
\end{enumerate}

\label{prop:semisimple-0-simplifying} 
A Boolean inverse semigroup is $0$-simplifying and semisimple if and only if it is isomorphic to
a Boolean inverse semigroup of the form $M_{|X|}(G^{0})$ for some non-empty set $X$ and group $G$.

\label{cor:watch} 
The simple, semisimple Boolean inverse semigroups are isomorphic to the semigroups $\mathscr{I}_{\rm {\tiny fin}}(X)$
where $X$ is a non-empty set.

\label{ex:choco} {\em The product of any finite number of semisimple semigroups is clearly semisimple, but this is not true of arbitrary direct products.
To see why, let $S = \mathscr{I}_{2} \times \mathscr{I}_{3} \times \mathscr{I}_{4} \times \ldots$.
This is a Boolean inverse monoid but clearly the number of elements below the identity element is infinite and so $S$ is not semisimple.}

\label{lem:restricted} \mbox{}
\begin{enumerate}
\item The restricted direct product of Boolean inverse semigroups is a Boolean inverse semigroup.
\item The restricted direct product of semisimple semigroups is semisimple.
\end{enumerate}

\label{them:dichotomy} Let $S$ be a $0$-simplifying Boolean inverse semigroup.
Then exactly one of the following is true:
\begin{enumerate}
\item $S$ is atomless.
\item $S$ is semisimple.
\end{enumerate}

{\em 
The type monoid of a Boolean inverse semigroup was introduced in \cite{KLLR2016, Wallis} and its theory further developed in \cite{Wehrung}.
It can be regarded as being the carrier of a notion of `dimension' for idempotents in the sense of von Neumann \cite{VN}
or as a carrier of a generalized notion of cardinality as in Tarski \cite{Tarski}.
}

\label{prop:type-monoids} 
Let $S$ be a Boolean inverse semigroup.
\begin{enumerate}
\item There is an order-iso\-morphism between the set of additive ideals of $S$ and the additive ideals of  $M_{\omega}(S)$.
In particular, each additive ideal of $M_{\omega}(S)$ is of the form $M_{\omega}(I)$ where $I$ is an additive ideal of $S$.
It follows that $S$ is $0$-simplifying if and only if $M_{\omega}(S)$ is $0$-simplifying.
\item $S$ is fundamental if and only if $M_{\omega}(S)$ is fundamental.
\item $S$ is semisimple if and only if $M_{\omega}(S)$ is semisimple.
\end{enumerate}

\label{prop:order-isomorphisms} 
Let $S$ be a Boolean inverse semigroup.
There are order-iso\-morphisms between:
\begin{enumerate}

\item The poset of self-conjugate $\vee$-closed order ideals of $\mathsf{E}(S)$. 

\item The poset of additive ideals of $S$ 

\item The poset of all $o$-ideals of the type monoid of $S$.

\end{enumerate}
